/* ------------------------------------------------------------------ public API (in-process) */

/** What other modules may call in-process: `ctx.use('departments')` (or `ctx.tryUse` for an optional dependency). */
export interface DepartmentsPublicApi {
  /** A picked farm machine with its attachments as product cards (prices and availability now), like GET /farm/machines/{productId}; NOT_FOUND when it isn't picked or the store no longer shows it. Farm orders price machines and attachments with it. Used by: farm. */
  getFarmMachine(productId: string): Promise<FarmMachine>;
  /** The customer's blog reactions, replies, reports, saved posts, followed authors and reply likes; company inquiries; company and game reviews; Play center player ID, scores and prize coupons, for the personal data export. Reactions, replies, reports and inquiries are kept by account id, the rest by customers-module id (both ids are looked up everywhere) Used by: customers. */
  exportCustomerData(input: { customerId: string, accountId: string }): Promise<common.CustomerDataSection[]>;
}

/* ------------------------------------------------------------------ tables (row types) */

/** Rows of this module's spec tables, as repositories read them from its collections (`departments.<table>`, ctx.mongo.table(name)). */
export interface DepartmentsDb {
  /** One row (id phones): the products of the Phone tab in order */
  phone_picks: {
    id: string;
    product_ids: Json;
    updated_by: string | null;
    updated_at: Date;
  };
  blog_topics: {
    id: string;
    slug: string;
    name: string;
    position: number;
    visible: boolean;
  };
  blog_authors: {
    id: string;
    slug: string;
    name: string;
    email: string | null;
    avatar: Json | null;
    bio: string | null;
    created_at: Date;
    updated_at: Date;
  };
  blog_posts: {
    id: string;
    slug: string;
    title: string;
    summary: string | null;
    body: string;
    cover: Json | null;
    topic_id: string | null;
    author_id: string;
    status: string;
    featured: boolean;
    published_at: Date | null;
    read_minutes: number;
    like_count: number;
    dislike_count: number;
    reply_count: number;
    created_at: Date;
    updated_at: Date;
  };
  blog_reactions: {
    id: string;
    post_id: string;
    customer_id: string;
    reaction: string;
    at: Date;
  };
  blog_replies: {
    id: string;
    post_id: string;
    parent_id: string | null;
    customer_id: string;
    author_name: string;
    text: string;
    status: string;
    /** customers who liked it */
    like_count: number;
    created_at: Date;
  };
  blog_reports: {
    id: string;
    target_type: string;
    target_id: string;
    reporter_id: string;
    reason: string;
    note: string | null;
    status: string;
    created_at: Date;
    decided_at: Date | null;
    decided_by: string | null;
  };
  industries: {
    id: string;
    slug: string;
    name: string;
    position: number;
    visible: boolean;
  };
  companies: {
    id: string;
    slug: string;
    name: string;
    logo: Json | null;
    industry_id: string | null;
    city: string | null;
    tagline: string | null;
    verified: boolean;
    description: string | null;
    photos: Json;
    founded: number | null;
    employees: string | null;
    contacts: Json;
    location: Json | null;
    status: string;
    position: number;
    created_at: Date;
    updated_at: Date;
  };
  inquiries: {
    id: string;
    company_id: string;
    customer_id: string | null;
    name: string;
    email: string;
    phone: string | null;
    message: string;
    status: string;
    staff_note: string | null;
    created_at: Date;
    updated_at: Date;
  };
  games: {
    id: string;
    slug: string;
    title: string;
    genre: string;
    icon: Json | null;
    cover: Json | null;
    players_label: string | null;
    featured: boolean;
    description: string | null;
    how_to_play: Json;
    /** tiers: ranks, reward, from_rank, to_rank, campaign_id */
    prizes: Json;
    prize_note: string | null;
    status: string;
    position: number;
    created_at: Date;
    updated_at: Date;
  };
  /** One row per game and period (today, week, all_time) */
  rankings: {
    id: string;
    game_id: string;
    period: string;
    entries: Json;
    updated_by: string | null;
    updated_at: Date;
  };
  /** Posts a customer saved (bookmarks) */
  blog_saves: {
    id: string;
    post_id: string;
    customer_id: string;
    saved_at: Date;
  };
  /** Authors a customer follows */
  blog_follows: {
    id: string;
    author_id: string;
    customer_id: string;
    followed_at: Date;
  };
  blog_reply_likes: {
    id: string;
    reply_id: string;
    post_id: string;
    customer_id: string;
    at: Date;
  };
  /** Customer reviews of companies and games: one per customer and target, editable */
  reviews: {
    id: string;
    target_type: 'company' | 'game';
    target_id: string;
    customer_id: string;
    /** first name and last initial when written */
    name: string;
    /** 1 to 5 */
    stars: number;
    text: string | null;
    hidden: boolean;
    hidden_reason: string | null;
    created_at: Date;
    updated_at: Date;
  };
  /** Play center player IDs: one stable short code per customer */
  players: {
    id: string;
    /** MK-XXXX-XXXX */
    code: string;
    customer_id: string;
    /** first name and last initial, refreshed when the customer opens it */
    name: string;
    created_at: Date;
    updated_at: Date;
  };
  /** Server keys of game partners; only a SHA-256 hash of each key is kept */
  game_keys: {
    id: string;
    game_id: string;
    key_hash: string;
    hint: string;
    status: 'active' | 'revoked';
    created_by: string | null;
    created_at: Date;
    last_used_at: Date | null;
    revoked_at: Date | null;
    revoked_by: string | null;
  };
  /** Scores game servers posted; day and week are the market day and the Monday of its prize week */
  scores: {
    id: string;
    game_id: string;
    partner_score_id: string;
    player_id: string;
    customer_id: string;
    score: number;
    played_at: Date;
    day: string;
    week: string;
    received_at: Date;
  };
  /** Prize weeks whose winners were worked out: done once every winner has a code */
  prize_weeks: {
    id: string;
    game_id: string;
    week: string;
    state: 'awarding' | 'done';
    winners: number;
    updated_at: Date;
  };
  /** One coupon per game, week and winner (promotions.issueCode, key play:<game>:<week>:<customer>) */
  prize_awards: {
    id: string;
    game_id: string;
    week: string;
    customer_id: string;
    name: string;
    rank: number;
    score: number;
    reward: string;
    campaign_id: string;
    code: string | null;
    code_id: string | null;
    state: 'issued' | 'failed';
    error: string | null;
    created_at: Date;
    updated_at: Date;
  };
  /** One row (id farm): machine types and the picked machines with their attachments */
  farm_setup: {
    id: string;
    types: Json;
    machines: Json;
    updated_by: string | null;
    updated_at: Date;
  };
}

